src='''def transform(grid):
    from collections import defaultdict
    g=[row[:] for row in grid]
    h,w=len(g),len(g[0])
    counts=defaultdict(int)
    for row in g:
        for x in row: counts[x]+=1
    bg=max(counts, key=counts.get)
    pts=defaultdict(list)
    for r in range(h):
        for c in range(w):
            if g[r][c]!=bg: pts[g[r][c]].append((r,c))
    for color, ps in pts.items():
        pair=None
        for a in ps:
            for b in ps:
                dr,dc=b[0]-a[0],b[1]-a[1]
                if abs(dr)==1 and abs(dc)==1:
                    pair=(a,b,dr,dc); break
            if pair: break
        if not pair: continue
        a,b,dr,dc=pair
        # Extend from the later point along the observed direction. If a marker
        # blocks that direction, extend backward from the earlier point instead.
        nr,nc=b[0]+dr,b[1]+dc
        if not (0<=nr<h and 0<=nc<w) or g[nr][nc]!=bg:
            r,c=a[0]-dr,a[1]-dc; dr,dc=-dr,-dc
        else:
            r,c=nr,nc
        while 0<=r<h and 0<=c<w and g[r][c]==bg:
            g[r][c]=color; r+=dr; c+=dc
    return g
'''
